let main = document.querySelector('main')
let box = document.querySelector('.box')
let teamNames = document.getElementById('h1')
let title = document.querySelector('h4')
let logo = document.getElementById('logo')
let fullName = document.getElementById('fullName')
let trophies = document.getElementById('trophies')
let seasons = document.getElementById('seasons')
let btn = document.getElementById('btn')



btn.addEventListener('click' , GuessTeam)

function GuessTeam(){
 
   let winner = arr[Math.floor(Math.random() * arr.length)];
    teamNames.innerHTML = winner.teamName
      main.style.background = `linear-gradient(135deg, ${winner.primaryColor}, ${winner.secondaryColor})`;
       box.style.backgroundColor = winner.secondaryColor
    title.innerHTML = "will be the winner of the 2026"
    logo.src = winner.logo
    fullName.innerHTML = winner.fullName
    trophies.innerHTML = winner.trophies

    seasons.innerHTML = winner.totalSeasons
}